from operator import add, mul, sub
from operator import floordiv as div

VALID_OPERATIONS = {'plus': add, 'minus': sub, 'multiplied by': mul, 'divided by': div}


def answer(question):
    text = question.strip()
    body = text.removesuffix('?')
    if body != 'What is' and not body.startswith('What is '):
        raise ValueError('unknown operation')
    if not text.endswith('?'):
        raise ValueError('syntax error')
    words = iter(body[len('What is'):].lower().split())

    def read_number():
        try:
            return int(next(words))
        except (StopIteration, ValueError) as error:
            raise ValueError('syntax error') from error

    result = read_number()
    for operation in words:
        if operation in ('multiplied', 'divided'):
            if next(words, None) != 'by':
                raise ValueError('syntax error')
            operation += ' by'
        if operation not in VALID_OPERATIONS:
            if operation.lstrip('+-').isdigit() or operation == 'by':
                raise ValueError('syntax error')
            raise ValueError('unknown operation')
        result = VALID_OPERATIONS[operation](result, read_number())
    return result
